// Read exact vendor recess contours and existing constructor cut templates.
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro {public static class LatchInProcess {
static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=64000000};
static string Hash(string p){using(var s=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
static Dictionary<string,object> O(object x){return(Dictionary<string,object>)x;}
static double[] N(object x){return ((Array)x).Cast<object>().Select(Convert.ToDouble).ToArray();}
static IEnumerable<int> Ids(object x){if(x is Array){foreach(object v in (Array)x)foreach(int id in Ids(v))yield return id;}else yield return Convert.ToInt32(x);}
static double[] P(IZMathPoint p){return new[]{p.X,p.Y,p.Z};}
static object Matrix(IZSceneElement e){var m=e.GetTransformToGlobal();var a=new List<double>();for(int i=0;i<4;i++)for(int j=0;j<4;j++)a.Add(m.GetValue(i,j));return a;}
static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}
static object State(IZBaseApp a){return ((Array)a.GetAllOpenDocs()??new object[0]).Cast<object>().Select(x=>{var d=D(x);return new{path=d.Name,guid=d.FileGUID,modified=d.Modified};}).OrderBy(x=>x.path).ToArray();}
static object Curves(IZProfile p){var list=new List<object>();foreach(object item in (Array)p.GetCurveIds()){int id=Convert.ToInt32(item);var kind=p.GetCurveType(id).ToString();var c=new Dictionary<string,object>{{"id",id},{"type",kind}};object a,b;double r,s,e;if(kind.Contains("LINE")&&!kind.Contains("SPLINE")){p.GetLineData(id,out a,out b);c["start"]=N(a);c["end"]=N(b);}else if(kind.Contains("ARC")&&!kind.Contains("ELLIP")){p.GetArcData(id,out a,out r,out s,out e);c["center"]=N(a);c["radius"]=r;c["start_angle"]=s;c["end_angle"]=e;}else if(kind.Contains("CIRCLE")){p.GetCircleData(id,out a,out r);c["center"]=N(a);c["radius"]=r;}else throw new Exception("Unsupported constructor curve "+kind);list.Add(c);}return list;}
static object Recess(IZPart p){var body=p.GetBody(true);var bf=(IZBodyFace)body;var be=(IZBodyEdge)body;int chosen=-1;double best=0;var options=new List<object>();
 foreach(object raw in (Array)body.GetFaceIds()){int id=Convert.ToInt32(raw);try{bool sense;ZMathPoint origin;ZMathVector normal;bf.GetPlaneData(id,out sense,out origin,out normal);if(Math.Abs(normal.Y)<.999)continue;double error,area;bf.GetFace(id).GetArea(1e-8,out error,out area);options.Add(new{id=id,y=origin.Y,area=area,bounds=bf.GetFaceBoundingBox(id)});if(origin.Y<-.004&&area>best){best=area;chosen=id;}}catch(COMException){}}
 if(chosen<0)throw new Exception("No measured planar recess face");var curves=new List<object>();foreach(object raw in (Array)bf.GetOuterEdgeIds(chosen)){int id=Convert.ToInt32(raw);ZMathPoint start,end,mid;ZMathVector tangent;be.GetEdgeStartInfo(id,out start,out tangent);be.GetEdgeEndInfo(id,out end,out tangent);be.GetEdgeMidInfo(id,out mid,out tangent);var c=new Dictionary<string,object>{{"id",id},{"type",be.get_CurveType(id).ToString()},{"start",P(start)},{"end",P(end)},{"mid",P(mid)}};try{bool sense;ZMathPoint center;ZMathVector axis;double radius;be.GetCircleData(id,out sense,out center,out axis,out radius);c["center"]=P(center);c["radius"]=radius;}catch(COMException){}curves.Add(c);}
 var flange=new List<object>();foreach(object faceRaw in (Array)body.GetFaceIds()){int fi=Convert.ToInt32(faceRaw);try{bool rev;ZMathPoint po;ZMathVector no;bf.GetPlaneData(fi,out rev,out po,out no);if(Math.Abs(no.Y)<.999||Math.Abs(po.Y)>1e-7)continue;var wires=new Dictionary<string,object>();foreach(string wire in new[]{"outer","inner"}){var edges=new List<object>();var ids=wire=="outer"?bf.GetOuterEdgeIds(fi):bf.GetInnerEdgeIds(fi);foreach(int ei in Ids(ids)){ZMathPoint st,en,mi;ZMathVector ta;be.GetEdgeStartInfo(ei,out st,out ta);be.GetEdgeEndInfo(ei,out en,out ta);be.GetEdgeMidInfo(ei,out mi,out ta);edges.Add(new{id=ei,type=be.get_CurveType(ei).ToString(),start=P(st),end=P(en),mid=P(mi),bounds=be.GetEdgeBoundingBox(ei)});}wires[wire]=edges;}flange.Add(new{id=fi,wires=wires});}catch(COMException){}}return new{face_id=chosen,area=best,contour=curves,face_candidates=options,flange=flange};
}
public static int Run(string folder){var report=new Dictionary<string,object>();IZDoc owned=null;IZBaseApp app=null;object before=null;bool passed=false;
 try{var req=O(J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if((string)req["contract"]!="rockpro-requested-mount-survey-v1"||System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(req["expected_pid"]))throw new Exception("Wrong host/request");dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");before=State(app);var outputs=new List<object>();int seq=0;
 foreach(object raw in (object[])req["models"]){var item=O(raw);string source=(string)item["file"],expected=(string)item["sha256"];if(Hash(source)!=expected)throw new Exception("Source changed");string copy=Path.Combine(folder,"input-"+(seq++)+".ics");File.Copy(source,copy,false);bool already;owned=app.OpenFile2(copy,false,false,out already);if(already){owned=null;throw new Exception("Ownership refused");}var scene=(IZSceneDoc)owned;var u=(IZSceneDocUtility)scene;var rows=new List<object>();
 foreach(object n in (object[])item["ids"]){int id=Convert.ToInt32(n);var e=u.GetElementById(id);var r=new Dictionary<string,object>{{"id",id},{"name",e.Name},{"matrix_m",Matrix((IZSceneElement)e)}};
 if(e.Type==eZElementType.Z_ELEMENT_PART){var p=(IZPart)e;r["bounds_m"]=p.GetBody(true).GetBoundingBox();if(item.ContainsKey("recess"))r["recess"]=Recess(p);
 if(item.ContainsKey("features")){var fm=(IZPartFeatureMgr)p;var fs=new List<object>();for(int i=0;i<fm.GetFeaturesCount();i++){var f=fm.GetFeatureAt(i);var fe=(IZElement)f;if(((object[])item["features"]).Length>0&&!((object[])item["features"]).Select(Convert.ToInt32).Contains(fe.Id))continue;var ex=f as IZExtrudeFeature;if(ex==null)continue;fs.Add(new{id=fe.Id,name=fe.Name,matrix_m=Matrix((IZSceneElement)f),profile_matrix_m=Matrix((IZSceneElement)ex.CrossSection),curves=Curves(ex.CrossSection),forward=ex.get_ExtrudeDistance(eZExtrudeDirectionType.Z_EXTRUDE_DIRECTION_FORWARD),backward=ex.get_ExtrudeDistance(eZExtrudeDirectionType.Z_EXTRUDE_DIRECTION_BACKWARD)});}r["features"]=fs;}}
 rows.Add(r);}outputs.Add(new{key=item["key"],rows=rows,source_sha256=expected});if(owned.Modified)throw new Exception("Read modified input copy");owned.Close();owned=null;if(Hash(source)!=expected)throw new Exception("Source integrity changed");}
 report["outputs"]=outputs;passed=true;
 }catch(Exception e){report["error"]=e.ToString();}
 finally{if(owned!=null)try{owned.Close2(true);}catch(Exception e){report["cleanup_error"]=e.ToString();passed=false;}if(app!=null&&before!=null){report["existing_documents_preserved"]=J.Serialize(before)==J.Serialize(State(app));if(!(bool)report["existing_documents_preserved"])passed=false;}report["passed"]=passed;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(report));}return passed?0:1;
}
}}
